WITH filtered AS (SELECT *, CASE WHEN rating >= 3.9 THEN 'High' WHEN rating >= 2.6 THEN 'Medium' ELSE 'Low' END AS rating_level, COALESCE(city, 'DIRECT') AS resolved_city FROM suppliers WHERE country = 'US') SELECT country, CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, SUM(CASE WHEN country = 'TH' THEN rating ELSE 0 END) AS th_rating, ROUND(AVG(rating), 2) AS avg_rating, STDDEV_SAMP(rating) AS rating_stddev FROM filtered GROUP BY GROUPING SETS ((country, CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END), (country))
